pub const CONTENT_TYPE:&str="application/vnd.aurora.policy.grant-integrity-card-1+json";
pub const BOUNDARY:&str="preclinical-research-only; no human-subject or clinical-source data; no diagnosis, treatment, triage, enrollment, or clinical decisions";
#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]pub struct AutonomyGrant4{pub grant_id:String,pub actor:String,pub action:String,pub scope:String,pub autonomy_tier:String,pub expiration_epoch:u64,pub policy_epoch:u64,pub revoked:bool,pub evidence_digest:ContentHash,pub local:bool,pub aggregate_only:bool}
