#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]pub struct GrantIntegrityArtifact4{pub artifact_id:String,pub content_type:String,pub content_hash:ContentHash,pub semantic_loss:Vec<String>,pub evidence_digests:Vec<ContentHash>,pub boundary:String}
#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]pub struct GrantIntegrityCard7{pub schema_version:String,pub contract_version:String,pub feature_id:String,pub mode:String,pub scale:String,pub request_id:String,pub purpose:String,pub disposition:String,pub grant_order:Vec<String>,pub allowed_order:Vec<String>,pub denied_order:Vec<String>,pub unknown_order:Vec<String>,pub omitted_order:Vec<String>,pub action_order:Vec<String>,pub scope_order:Vec<String>,pub tier_order:Vec<String>,pub expiration_order:Vec<String>,pub revocation_order:Vec<String>,pub replay_identity:ContentHash,pub closure_digest:ContentHash,pub artifact:GrantIntegrityArtifact4,pub effect_receipts:Vec<String>,pub raw_data_local:bool,pub aggregate_only:bool,pub boundary:String}
#[derive(Debug,Error,Clone,PartialEq,Eq)]pub enum GrantIntegrityError{#[error("invalid grant-integrity request: {0}")]Invalid(String),#[error("grant-integrity card failed validation: {0}")]Output(String)}
fn ordered(v:&[String])->bool{v.windows(2).all(|p|p[0]<p[1])}fn digest(v:&ContentHash)->bool{v.as_str().len()==64&&v.as_str().bytes().all(|b|b.is_ascii_hexdigit())}fn nonempty(v:&str)->bool{!v.trim().is_empty()}
pub fn manifest(id:&str,version:&str,scale:&str,mode:&str)->serde_json::Value{json!({"schema_version":"1.0.0","capability_id":id,"version":version,"owner_crate":"policy","consumers":["autonomy broker","instrument gateway","federation admission","release auditor"],"behavior":format!("qualify expiring autonomy grants at {scale} ({mode})"),"value":"prevents revoked, expired, over-scoped, or over-tier grants from authorizing research effects","input_schema":"GrantIntegrityRequest4@1","output_schema":"GrantIntegrityCard7@1","effects":["emit:grant-card","retain:revocation","block:unauthorized-effect"],"permissions":["read:local-policy"],"determinism":"byte_stable","autonomy_tier":"A1","boundary":BOUNDARY})}
impl GrantIntegrityCard7{pub fn validate(&self)->Result<(),GrantIntegrityError>{if self.schema_version!="1.0.0"||!nonempty(&self.contract_version)||!nonempty(&self.feature_id)||!nonempty(&self.mode)||!nonempty(&self.scale)||!nonempty(&self.request_id)||!nonempty(&self.purpose)||self.boundary!=BOUNDARY||!self.raw_data_local||!self.aggregate_only||self.grant_order.is_empty()||!ordered(&self.grant_order)||!ordered(&self.allowed_order)||!ordered(&self.denied_order)||!ordered(&self.unknown_order)||!ordered(&self.omitted_order)||!ordered(&self.action_order)||!ordered(&self.scope_order)||!ordered(&self.tier_order)||!ordered(&self.expiration_order)||!ordered(&self.revocation_order)||!digest(&self.replay_identity)||!digest(&self.closure_digest)||self.artifact.content_type!=CONTENT_TYPE||self.artifact.content_hash!=self.closure_digest||self.artifact.boundary!=BOUNDARY{return Err(GrantIntegrityError::Output("grant identity, ordering, locality, digest, or artifact is invalid".into()))}let ids=BTreeSet::from_iter(self.grant_order.iter().cloned());let states=self.allowed_order.iter().chain(&self.denied_order).chain(&self.unknown_order).chain(&self.omitted_order).cloned().collect::<Vec<_>>();if ids.len()!=self.grant_order.len()||states.len()!=ids.len()||BTreeSet::from_iter(states)!=ids{return Err(GrantIntegrityError::Output("grant states do not partition".into()))}Ok(())}}
pub fn qualify(request:&GrantIntegrityRequest4,id:&str,version:&str,scale:&str,mode:&str)->Result<GrantIntegrityCard7,GrantIntegrityError>{if !nonempty(&request.request_id)||!nonempty(&request.purpose)||request.grants.is_empty()||request.required_grant_order.is_empty()||request.required_action_order.is_empty()||!nonempty(&request.maximum_tier)||!digest(&request.replay_identity)||request.boundary!=BOUNDARY||!request.raw_data_local||!request.aggregate_only||!ordered(&request.required_grant_order)||!ordered(&request.required_action_order)||!ordered(&request.adversarial_events){return Err(GrantIntegrityError::Invalid("grant identity, requirements, tier, digest, ordering, locality, or boundary is invalid".into()))}let mut rows=request.grants.clone();rows.sort_by(|a,b|a.grant_id.cmp(&b.grant_id));let mut seen=BTreeSet::new();let mut order=Vec::new();let mut allowed=BTreeSet::new();let mut denied=BTreeSet::new();let mut unknown=BTreeSet::new();let mut omitted=BTreeSet::new();let mut actions=BTreeSet::new();let mut scopes=BTreeSet::new();let mut tiers=BTreeSet::new();let mut expirations=BTreeSet::new();let mut revocations=BTreeSet::new();let mut digests=BTreeSet::new();for g in &rows{if !seen.insert(g.grant_id.clone())||!nonempty(&g.grant_id)||!nonempty(&g.actor)||!nonempty(&g.action)||!nonempty(&g.scope)||!nonempty(&g.autonomy_tier)||!digest(&g.evidence_digest)||!g.local||!g.aggregate_only{return Err(GrantIntegrityError::Invalid("grant identity, actor, scope, tier, evidence, or locality is invalid".into()))}order.push(g.grant_id.clone());actions.insert(g.action.clone());scopes.insert(g.scope.clone());tiers.insert(g.autonomy_tier.clone());expirations.insert(format!("{}:{}",g.grant_id,g.expiration_epoch));digests.insert(g.evidence_digest.clone());if g.revoked{revocations.insert(format!("{}:revoked",g.grant_id));}if g.policy_epoch==0||g.evidence_digest==request.replay_identity{unknown.insert(g.grant_id.clone());}else if g.revoked||g.expiration_epoch<request.current_epoch||g.autonomy_tier>request.maximum_tier||!request.required_action_order.contains(&g.action){denied.insert(g.grant_id.clone());}else if !request.required_grant_order.contains(&g.grant_id){omitted.insert(g.grant_id.clone());}else{allowed.insert(g.grant_id.clone());}}let global=!request.policy_allowed||!request.protected_closure||!request.signed_approval||!request.raw_data_local||!request.aggregate_only||!request.adversarial_events.is_empty()||request.action_count>request.action_budget;if global{omitted.extend(order.iter().cloned());allowed.clear();denied.clear();unknown.clear();}let missing=!request.required_grant_order.iter().all(|g|seen.contains(g))||!request.required_action_order.iter().all(|a|actions.contains(a));let disposition=if global{"blocked"}else if missing{"unknown"}else if !denied.is_empty()||!unknown.is_empty()||!omitted.is_empty(){"partial"}else{"qualified"};let mut payload=json!({"schema_version":"1.0.0","contract_version":version,"feature_id":id,"mode":mode,"scale":scale,"request_id":request.request_id,"purpose":request.purpose,"disposition":disposition,"grant_order":order,"allowed_order":allowed.into_iter().collect::<Vec<_>>(),"denied_order":denied.into_iter().collect::<Vec<_>>(),"unknown_order":unknown.into_iter().collect::<Vec<_>>(),"omitted_order":omitted.into_iter().collect::<Vec<_>>(),"action_order":actions.into_iter().collect::<Vec<_>>(),"scope_order":scopes.into_iter().collect::<Vec<_>>(),"tier_order":tiers.into_iter().collect::<Vec<_>>(),"expiration_order":expirations.into_iter().collect::<Vec<_>>(),"revocation_order":revocations.into_iter().collect::<Vec<_>>(),"replay_identity":request.replay_identity,"raw_data_local":true,"aggregate_only":true,"boundary":BOUNDARY});let hash=ContentHash::of_value(&payload).map_err(|e|GrantIntegrityError::Output(e.to_string()))?;payload["closure_digest"]=json!(hash);payload["artifact"]=json!({"artifact_id":format!("policy-grant:{}",request.request_id),"content_type":CONTENT_TYPE,"content_hash":hash,"semantic_loss":payload["omitted_order"],"evidence_digests":digests.into_iter().collect::<Vec<_>>(),"boundary":BOUNDARY});payload["effect_receipts"]=json!(if disposition=="qualified"{vec![format!("emit:grant-card:{}",request.request_id)]}else{vec!["block:unauthorized-effect".to_string()]});let out:GrantIntegrityCard7=serde_json::from_value(payload).map_err(|e|GrantIntegrityError::Output(e.to_string()))?;out.validate()?;Ok(out)}
